    "property_id": "PROP-kintai-v3-st-pre-002",
    "audit_result": {
      "property_id": "PROP-kintai-v3-st-pre-002",
      "classification": "vulnerability",
      "code_path": "src/app/auth/callback/route.ts::GET::L17-18,L151",
      "proof_trace": "The redirect URL is constructed as `${origin}${next}` where `next` comes from the unvalidated `auth_next` cookie or `?next=` query parameter (L17-18). No check enforces that `next` starts with `/` or excludes `@`, so an attacker-controlled value like `@evil.com/phishing` produces `https://app.example.com@evil.com/phishing`, which all major browsers parse with `evil.com` as the host (RFC 3986 userinfo syntax). The `auth_next` cookie is itself set from unvalidated FormData in `actions.ts:286` (`signInWithDiscord`), giving attackers a second injection point.",
      "attack_scenario": "Attacker submits `signInWithDiscord` with `next=@evil.com/phishing` (via a CSRF-style cross-site form post), setting the victim's `auth_next` cookie. After the victim completes Discord OAuth, the callback at L151 issues `NextResponse.redirect('https://app.example.com@evil.com/phishing')`, which browsers interpret as a redirect to `https://evil.com/phishing`.",
      "checklist_id": "PROP-kintai-v3-st-pre-002"
    },
    "text": "auth_next cookie redirect target must be validated against same-origin allowlist.",
    "assertion": "forall redirect: use_auth_next(redirect) => is_same_origin(redirect) == true",
    "covers": "SG-006",
    "severity": "MEDIUM",
    "type": "pre-condition"
  }
}

